import re
seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq); S=str.maketrans('ACGT','TGCA'); rc=seq.translate(S)[::-1]
best=None
for nm,s in (('+',seq),('-',rc)):
    for f in range(3):
        t=s[f:]
        for m in re.finditer('ATG', t):
            i=m.start(); j=i
            while j+3<=len(t) and t[j:j+3] not in {'TAA','TAG','TGA'}: j+=3
            aa=(j-i)//3
            if best is None or aa>best[0]:
                a,b=i+f, j+f  # 0-based in s
                if nm=='+': coords=(a+1, b)
                else: coords=(n-b+1, n-a)
                best=(aa,nm,f+1,coords)
print(best)
